mapper.update:
UPDATE emp14_account
   SET emp14_start_date = #{req.startDate}
     , emp14_bank_cd    = #{req.bankCd}
     , emp14_account_no = CASE WHEN #{req.accountNoDec} IS NOT NULL
                               THEN TO_ENCRYPTS(#{req.accountNoDec})
                               ELSE emp14_account_no END
     , emp14_note       = #{req.note}
 WHERE emp14_account_id = #{accountId}
   AND emp14_company_id = #{companyId}

mapper.delete:
DELETE FROM emp14_account
 WHERE emp14_company_id = #{companyId}
   AND emp14_account_id IN
#{id}
